// src/app/skills/page.tsx
"use client";

import { useState, useEffect } from "react";
import dynamic from "next/dynamic";
import NavBar from "@/components/NavBar";
import ParticlesBackground from "@/components/ParticlesBackground";
import LoadingSpinner from "@/components/Loading";
import { skills, skillCategories } from "@/data/projects";

const MotionDiv = dynamic(
  () => import("framer-motion").then((mod) => mod.motion.div),
  { ssr: false },
);

export default function Skills() {
  const [mounted, setMounted] = useState(false);
  const [activeCategory, setActiveCategory] = useState<string | null>(null);

  useEffect(() => {
    setMounted(true);
    // Set default category
    if (skillCategories.length > 0) {
      setActiveCategory(skillCategories[0]);
    }
  }, []);

  if (!mounted) {
    return <LoadingSpinner />;
  }

  const filteredSkills = activeCategory
    ? skills.filter((skill) => skill.category === activeCategory)
    : skills;

  return (
    <div className="min-h-screen flex flex-col justify-center items-center relative">
      <NavBar />
      <ParticlesBackground />

      <div className="container mx-auto px-4 py-24 z-10">
        <MotionDiv
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5 }}
          className="text-center mb-12"
        >
          <h1 className="text-4xl font-bold mb-6">My Skills</h1>
          <p className="text-lg max-w-2xl mx-auto">
            Here's a comprehensive overview of my technical skills and
            proficiency levels. Click on the categories to filter.
          </p>
        </MotionDiv>

        {/* Category Tabs */}
        <div className="flex flex-wrap justify-center gap-4 mb-12">
          {skillCategories.map((category, index) => (
            <button
              key={category}
              onClick={() => setActiveCategory(category)}
              className={`px-4 py-2 rounded-lg text-sm transition-all ${
                activeCategory === category
                  ? "bg-primary text-white"
                  : "bg-white/10 hover:bg-white/20"
              }`}
            >
              {category}
            </button>
          ))}
        </div>

        {/* Skills Grid */}
        <MotionDiv
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ duration: 0.5 }}
          className="card p-8"
        >
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            {filteredSkills.map((skill, index) => (
              <MotionDiv
                key={skill.name}
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.3, delay: index * 0.1 }}
                className="bg-white/5 p-4 rounded-lg"
              >
                <div className="flex justify-between mb-2">
                  <span className="font-semibold">{skill.name}</span>
                  <span className="text-primary">{skill.level}%</span>
                </div>
                <div className="w-full bg-white/10 rounded-full h-2.5">
                  <MotionDiv
                    initial={{ width: 0 }}
                    animate={{ width: `${skill.level}%` }}
                    transition={{ duration: 1, delay: 0.2 }}
                    className="bg-primary h-2.5 rounded-full"
                  />
                </div>
              </MotionDiv>
            ))}
          </div>
        </MotionDiv>

        {/* Additional Info */}
        <MotionDiv
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5, delay: 0.3 }}
          className="text-center mt-12 max-w-2xl mx-auto"
        >
          <h2 className="text-2xl font-bold mb-4">Continuous Learning</h2>
          <p>
            I'm always looking to expand my knowledge and stay updated with the
            latest technologies. Currently, I'm focused on learning more about
            game development with Unity and exploring advanced concepts in data
            structures and algorithms.
          </p>
        </MotionDiv>
      </div>
    </div>
  );
}
